-- mod-temucraft-lostlands: creature templates (5187). Re-runnable: deletes its own ID range first.
-- Change @CRE to move every creature; spawns, loot, quests and gossip follow.
SET @CRE := 1200000;
SET @LOOT := 1200000; SET @LOOT_PICK := 1200000; SET @LOOT_SKIN := 1200000;
SET @GOSSIP := 1200000;
DELETE FROM `creature_template` WHERE `entry` BETWEEN @CRE AND @CRE+5188;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN @CRE AND @CRE+5188;
DELETE FROM `creature_template_resistance` WHERE `CreatureID` BETWEEN @CRE AND @CRE+5188;
DELETE FROM `creature_template_spell` WHERE `CreatureID` BETWEEN @CRE AND @CRE+5188;
DELETE FROM `creature_template_addon` WHERE `entry` BETWEEN @CRE AND @CRE+5188;
DELETE FROM `creature_template_movement` WHERE `CreatureId` BETWEEN @CRE AND @CRE+5188;
DELETE FROM `creature_equip_template` WHERE `CreatureID` BETWEEN @CRE AND @CRE+5188;
DELETE FROM `creature_default_trainer` WHERE `CreatureId` BETWEEN @CRE AND @CRE+5188;
DELETE FROM `trainer` WHERE `Id` BETWEEN @CRE AND @CRE+5188;
DELETE FROM `trainer_spell` WHERE `TrainerId` BETWEEN @CRE AND @CRE+5188;
